class QualcommUeTranslator:
    pool_name = 'QualcommUePool'
    capabilities = ['REAL_UE', 'REAL_QUALCOMM_UE']
    class_name = pool_name.split('Pool')[0]

    @classmethod
    def translate(cls, qualcomm_ues, taf_configuration):
        qualcomm_info = {}
        for ue_no, ue in enumerate(qualcomm_ues):
            ue_name = cls._create_ue_name(ue_no)

            configuration = cls._get_configuration_info(ue)

            constructor_parameters = {'serial_number': ue.serial_number,
                                      'configuration': configuration}

            all_capabilities = cls._get_capabilities(ue)

            qualcomm_info[ue_name] = {'CAPABILITIES': all_capabilities,
                                      'CLASS': cls.class_name,
                                      'CONSTRUCTOR_PARAMETERS': constructor_parameters}

        return {'inline_config': qualcomm_info}

    @classmethod
    def _create_ue_name(cls, ue_no):
        ue_name = f'{cls.pool_name}_{ue_no}'
        return ue_name

    @classmethod
    def _get_capabilities(cls, ue):
        if ue.capabilities is not None:
            return cls.capabilities + ue.capabilities
        return cls.capabilities

    @staticmethod
    def _get_app_server(ue):
        app_server = {'ssh': {'host': ue.iperf_details.ssh_connection_details.addr,
                              'user': ue.iperf_details.ssh_connection_details.username,
                              'password': ue.iperf_details.ssh_connection_details.password},
                      'lte_network_ip': ue.iperf_details.network_interface_address}  # LTE? network ip?
        return app_server

    @staticmethod
    def _get_port_dict(ue):
        port_dict = {'heartbeat': ue.heartbeat_port,
                     'server_command_input': ue.server_command_input_port,
                     'server_qxdm_messages': ue.server_qxdm_messages_port,
                     'server_command_output': ue.server_command_output_port,
                     'message_stream_port': ue.message_stream_port}
        return port_dict

    @classmethod
    def _get_configuration_info(cls, ue):
        port_dict = cls._get_port_dict(ue)

        ssh_conn = ue.ssh_connection_details
        configuration = {'ue_pc_host': ssh_conn.addr,
                         'port_dict': port_dict,
                         'login': ssh_conn.username,
                         'password': ssh_conn.password,
                         'com_port': ue.com_port,
                         'qxdm_version': ue.qxdm_version,
                         'licence_type': ue.license_type,
                         'ue_type': ue.ue_type,
                         'iperf_adb_dir': ue.iperf_details.iperf_path}
        if ue.iperf_details is not None:
            configuration['data_transfer'] = cls._get_app_server(ue)
        return configuration


class AndroidUeTranslator:
    pool_name = 'AndroidUePool'
    capabilities = ['REAL_UE', 'REAL_ANDROID_UE']
    pyro_port = '9090'
    class_name = pool_name.split('Pool')[0]

    @classmethod
    def translate(cls, android_ues, taf_configuration):
        android_info = {}
        for ue_no, ue in enumerate(android_ues):
            ue_name = cls._create_ue_name(ue_no)
            all_capabilities = cls._get_capabilities(ue)
            configuration = cls._get_configuration_info(ue)

            constructor_parameters = {'serial_number': ue.serial_number,
                                      'configuration': configuration}

            class_name = ue.class_name.value if hasattr(ue, 'class_name') else cls.class_name
            android_info[ue_name] = {'CAPABILITIES': all_capabilities,
                                     'CLASS': class_name,
                                     'CONSTRUCTOR_PARAMETERS': constructor_parameters}
        return {'inline_config': android_info}

    @classmethod
    def _create_ue_name(cls, ue_no):
        ue_name = f'{cls.pool_name}_{ue_no}'
        return ue_name

    @classmethod
    def _get_capabilities(cls, ue):
        if ue.capabilities is not None:
            return cls.capabilities + ue.capabilities
        return cls.capabilities

    @staticmethod
    def _get_app_server_connection_details(ue):
        app_server = {'ssh': {'host': ue.iperf_details.ssh_connection_details.addr,
                              'user': ue.iperf_details.ssh_connection_details.username,
                              'password': ue.iperf_details.ssh_connection_details.password}
                      }
        return app_server

    @staticmethod
    def _get_app_server_details(app_server):
        app_server_data = {}
        app_server_details = ['host', 'user', 'password', 'iperf_interface_ip']
        for app_server_detail in app_server_details:
            try:
                app_server_detail_value = getattr(app_server, app_server_detail)
                if app_server_detail:
                    app_server_data[app_server_detail] = app_server_detail_value
            except AttributeError:
                pass
        return app_server_data

    @classmethod
    def _get_app_servers_info(cls, ue, configuration):
        configuration['data_transfer']['app_servers'] = {}
        for app_server in ue.app_servers:
            try:
                app_server_name_value = getattr(app_server, 'app_server_name')
                if app_server_name_value:
                    configuration['data_transfer']['app_servers'][str(app_server_name_value)] = \
                        cls._get_app_server_details(app_server)
            except AttributeError:
                pass

    @staticmethod
    def _get_ping_info(ue, configuration):
        configuration['data_transfer']['ping'] = {}
        ping_options = ['ping_host_ip', 'ping_count', 'allowed_packet_loss']
        for ping_option in ping_options:
            try:
                ping_option_value = getattr(ue.iperf_details.ping, ping_option)
                if ping_option_value is not None:
                    configuration['data_transfer']['ping'][ping_option] = str(ping_option_value)
            except AttributeError:
                pass

    @staticmethod  # noqa: C901  - added due to CI/CD job failing (old error)
    def _get_iperf_options(ue, configuration):
        configuration['data_transfer']['iperf_options'] = {}
        iperf_options = ['parallel_streams', 'packet', 'buffer', 'ttl', 'max_segment_size', 'linux_congestion',
                         'data_file', 'output_file', 'enhanced_reports']
        for iperf_option in iperf_options:
            try:
                iperf_option_value = getattr(ue.iperf_details.iperf_options, iperf_option)
                if iperf_option_value is not None:
                    configuration['data_transfer']['iperf_options'][iperf_option] = \
                        iperf_option_value if isinstance(iperf_option_value, bool) else str(iperf_option_value)
            except AttributeError:
                pass
        try:
            if ue.iperf_details.iperf_options.qci is not None:
                configuration['data_transfer']['iperf_options']['qci'] = ue.iperf_details.iperf_options.qci
        except AttributeError:
            pass

    @staticmethod
    def _get_pdns(ue):
        pdns = {}
        parameters = ['authType', 'mcc', 'mnc', 'carrierEnabled', 'operatorNumeric', 'protocol', 'roamingProtocol',
                      'proxyAddress', 'proxyPort', 'mmsc', 'mmsProxyAdderss', 'mmsProxyPort', 'user', 'password',
                      'mvnoType', 'networkType']
        for pdn in ue.pdn:
            pdns[str(pdn.entryName)] = {'entryName': pdn.entryName,
                                        'apn': pdn.apn,
                                        'apnType': tuple(pdn.apnType)}
            for parameter in parameters:
                parameter_value = getattr(pdn, parameter)
                if parameter_value:
                    pdns[str(pdn.entryName)][parameter] = parameter_value
        return pdns

    @classmethod  # noqa: C901  - added due to CI/CD job failing (old error)
    def _get_optional_configuration_parameters(cls, ue, configuration):
        parameters = ['qcat_path', 'diag_cfg_path', 'service_call_attach', 'service_call_detach',
                      'network_mode_switch_method', 'imei', 'imsi', 'phone_number', 'qcat_analyzer',
                      'voice_call_technology', 'voice_call_technology_timeout', 'voice_call_dialing_technology',
                      'processes_to_kill', 'clear_logs', 'clear_server_files', 'is_rooted', 'qualcomm_prototype',
                      'serial_com', 'diag_com', 'interface_name', 'cid', 'reset_interface', 'enable_disable_cfun',
                      'restart_wwansvc', 'mobile_network_text', 'setting_network_mode_text', 'secret_code',
                      'airplane_mode_switcher_text',
                      'airplane_mode_confirm_button_text']
        for parameter in parameters:
            try:
                parameter_value = getattr(ue, parameter)
                if parameter_value is not None:
                    configuration[parameter] = \
                        parameter_value if isinstance(parameter_value, bool) else str(parameter_value)
            except AttributeError:
                pass
        try:
            if ue.pdn is not None:
                configuration['PDN'] = cls._get_pdns(ue)
        except AttributeError:
            pass

    @classmethod  # noqa: C901  - added due to CI/CD job failing (old error)
    def _get_data_transfer_parameters(cls, ue, configuration):  # noqa: C901
        configuration['data_transfer'] = {}
        if ue.app_servers is None:
            configuration['data_transfer'] = cls._get_app_server_connection_details(ue)
        dt_parameters = ['iperf_path', 'iperf_mode', 'serial_number', 'iperf_interval', 'server_close_delay',
                         'traffic_type', 'iperf_version']
        for parameter in dt_parameters:
            try:
                parameter_value = getattr(ue.iperf_details, parameter)
                if parameter_value is not None:
                    configuration['data_transfer'][parameter] = str(parameter_value)
            except AttributeError:
                pass
        try:
            if ue.iperf_details.iperf_bind_ue_ip is not None:
                configuration['data_transfer']['iperf_options']['iperf_bind_ue_ip'] = ue.iperf_details.iperf_bind_ue_ip
        except AttributeError:
            pass
        if ue.iperf_details.network_interface_address is not None:
            configuration['data_transfer']['iperf_interface_ip'] = ue.iperf_details.network_interface_address
        try:
            if ue.iperf_details.network_interface_name is not None:
                configuration['data_transfer']['iperf_interface_name'] = ue.iperf_details.network_interface_name
        except AttributeError:
            pass
        try:
            if ue.iperf_details.ping is not None:
                cls._get_ping_info(ue, configuration)
        except AttributeError:
            pass
        try:
            if ue.iperf_details.iperf_options is not None:
                cls._get_iperf_options(ue, configuration)
        except AttributeError:
            pass

        try:
            if ue.app_servers is not None:
                cls._get_app_servers_info(ue, configuration)
        except AttributeError:
            pass

    @classmethod
    def _get_configuration_info(cls, ue):
        ssh_conn = ue.ssh_connection_details
        configuration = {'ue_pc_ip': ssh_conn.addr,
                         'pyro_port': cls.pyro_port,
                         'login': ssh_conn.username,
                         'password': ssh_conn.password,
                         'server_dir': ue.server_dir,
                         'server_python': ue.python_path
                         }

        cls._get_optional_configuration_parameters(ue, configuration)
        # to switch to ute_ue IperfDataTransfer:
        # configuration['data_transfer'] = UteUeIperfDataTransferTranslator.get_data_transfer_descr(ue)
        if ue.iperf_details is not None:
            cls._get_data_transfer_parameters(ue, configuration)
        return configuration


class TafUeBaseTranslator:
    __metaclass__ = abc.ABCMeta

    """ NOTE! Overwrite ue_identifier, pool_name, class_name & capabilities in your translator! """
    ue_identifier = 'serial_number'
    pool_name = 'UePool'
    capabilities = ['REAL_UE']
    class_name = pool_name.split('Pool')[0]

    @classmethod
    @abc.abstractmethod
    def _get_specific_constructor_parameters(cls, ue):
        """ Note! for AT Commands translator change ue_identifier to 'com_port'
            and add optional parameters (like 'serial_number') this way:
            return: {'serial_number': ue.serial_number}
            return: dict
        """
        pass

    @classmethod
    @abc.abstractmethod
    def _get_data_transfer_with_parameters(cls):
        """ return dictionary of data transfer protocol with their parameters
            return: dict
        """
        pass

    @classmethod
    @abc.abstractmethod
    def _get_optional_configuration_params(cls):
        """ return list of configuration parameters
            return: list
        """
        pass

    @classmethod
    def _get_ue_identifier(cls, ue):
        if getattr(ue, cls.ue_identifier):
            dictionary = {cls.ue_identifier: getattr(ue, cls.ue_identifier)}
            if cls._get_specific_constructor_parameters(ue):
                dictionary.update(cls._get_specific_constructor_parameters(ue))
            return dictionary
        else:
            return {}

    @classmethod
    def translate(cls, given_ues, taf_configuration):
        ue_info = {}

        for ue_no, ue in enumerate(given_ues):
            ue_name = cls._create_ue_name(ue_no)
            all_capabilities = cls._get_capabilities(ue)
            configuration = cls._get_configuration_info(ue)
            constructor_parameters_dict = {'configuration': configuration}
            if cls._get_ue_identifier(ue):
                constructor_parameters_dict.update(cls._get_ue_identifier(ue))
            constructor_parameters = constructor_parameters_dict
            class_name = ue.class_name.value if hasattr(ue, 'class_name') else cls.class_name
            ue_info[ue_name] = {'CAPABILITIES': all_capabilities,
                                'CLASS': class_name,
                                'CONSTRUCTOR_PARAMETERS': constructor_parameters}
        return {'inline_config': ue_info}

    @classmethod
    def _create_ue_name(cls, ue_no):
        ue_name = f'{cls.pool_name}_{ue_no}'
        return ue_name

    @classmethod
    def _get_capabilities(cls, ue):
        if ue.capabilities is not None:
            return ue.capabilities
        return cls.capabilities

    @classmethod
    def _get_configuration_info(cls, ue):
        # TODO possible usage of:
        # ssh_conn = ue.ssh_connection_details
        configuration = {'ue_pc_address': ue.ue_pc_address}

        cls._get_optional_configuration_parameters(ue, configuration)
        return configuration

    @classmethod  # noqa: C901
    def _get_optional_configuration_parameters(cls, ue, configuration):  # noqa: C901
        parameters = cls._get_optional_configuration_params()
        for parameter in parameters:
            try:
                parameter_value = getattr(ue, parameter)
                if parameter_value is not None:
                    configuration[parameter] = \
                        parameter_value if isinstance(parameter_value, bool) else str(parameter_value)
            except AttributeError:
                pass

        try:
            # to switch to ute_ue IperfDataTransfer:
            # configuration['data_transfer'] = UteUeIperfDataTransferTranslator.get_data_transfer_descr(ue)
            if ue.data_transfer is not None:
                cls._get_data_transfer_parameters(ue, configuration)
        except AttributeError:
            pass

        try:
            if ue.pdns is not None:
                cls._get_pdns(ue, configuration)
        except AttributeError:
            pass

    @staticmethod
    def _get_pdns(ue, configuration):
        pdns = {}
        optional_parameters = ['authType',
                               'mcc',
                               'mnc',
                               'carrierEnabled',
                               'operatorNumeric',
                               'protocol',
                               'roamingProtocol',
                               'proxyAddress',
                               'proxyPort',
                               'mmsc',
                               'mmsProxyAddress',
                               'mmsProxyPort',
                               'user',
                               'password',
                               'mvnoType',
                               'networkType']

        for pdn in ue.pdns:
            # Mandatory parameters
            try:
                entry_name = getattr(pdn, 'entryName')
                apn = getattr(pdn, 'apnName') if hasattr(pdn, 'apnName') else getattr(pdn, 'apn')
                apn_type = getattr(pdn, 'apnType')

                pdns[entry_name] = {'entryName': entry_name,
                                    'apnName': apn,
                                    'apnType': apn_type}
            except AttributeError:
                raise Exception('One or more mandatory parameters are missing !!! '
                                'Check if exist: {}, {} and {}'.format('entryName', 'apn', 'apnType'))
            # Optional parameters
            for parameter in optional_parameters:
                parameter_value = getattr(pdn, parameter)
                if parameter_value:
                    pdns[entry_name][parameter] = parameter_value

            configuration['pdns'] = pdns

    @classmethod
    def _get_data_transfer_parameters(cls, ue, configuration):
        configuration['data_transfer'] = {}
        protocols = ['iperf',
                     'ping',
                     'ftp']

        for protocol in ue.data_transfer:
            try:
                protocol_name = getattr(protocol, 'protocol_name')
                if protocol_name:
                    protocol_name = protocol_name.lower()
                    if protocol_name in protocols:
                        configuration['data_transfer'][str(protocol_name)] = \
                            cls._get_protocol_details(protocol, protocol_name)
                    else:
                        raise Exception(f'Provided protocol {protocol_name} is not supported!!!\n'
                                        f'Possible protocols are: {protocols}')
            except AttributeError:
                pass

    @classmethod  # noqa: C901
    def _get_protocol_details(cls, protocol, protocol_name):
        protocol_data = {}
        protocol_parameters = cls._get_data_transfer_with_parameters().get(protocol_name)

        try:
            app_server = getattr(protocol, 'app_server')
            protocol_data['app_server'] = cls._get_app_server_details(app_server)
        except AttributeError:
            pass

        for protocol_parameter in protocol_parameters:
            try:
                protocol_parameter_value = getattr(protocol, protocol_parameter)
                if protocol_parameter:
                    protocol_data[protocol_parameter] = protocol_parameter_value
            except AttributeError:
                pass
        return protocol_data

    @classmethod
    def _get_app_server_details(cls, app_server):
        app_server_data = {}
        app_server_details = ['app_server_name',
                              'address',
                              'user',
                              'password',
                              'bind_interface_ip',
                              'expected_prompt',
                              'binary_path',
                              'ports']

        for app_server_detail in app_server_details:
            try:
                app_server_detail_value = getattr(app_server, app_server_detail)
                if app_server_detail:
                    app_server_data[app_server_detail] = app_server_detail_value
            except AttributeError:
                pass
        return app_server_data


