    capabilities = ['REAL_UE', 'REAL_MTK_UE']
    class_name = pool_name.split('Pool')[0]

    @classmethod
    def _get_specific_constructor_parameters(cls, ue):
        return {'serial_number': ue.serial_number}

    @classmethod
    def _get_data_transfer_with_parameters(cls):
        return {'iperf': ['protocol_name',
                          'interval',
                          'binary_path',
                          'interface_name',
                          'server_close_delay',
                          'bind_ue_ip',
                          'version'],
                'ping': ['protocol_name',
                         'interval'],
                'ftp': ['protocol_name',
                        'interval']}

    @classmethod
    def _get_optional_configuration_params(cls):
        return ['phone_number',
                'ue_pc_port',
                'com_port',
                'edb_file_path',
                'log_filter',
                'proxy_mngr_port',
                'ueproxy_force_release',
                'imei',
                'imsi',
                'default_pdn_name',
                'processes_to_kill',
                'download_proxy_logs',
                'compress_proxy_logs',
                'compress_all_logs',
                'force_restart',
                'allow_kw_logs']

