class MediaTekTranslator:
    pool_name = 'MediaTekUePool'
    capabilities = ['REAL_UE', 'REAL_MEDIATEK_UE']
    class_name = pool_name.split('Pool')[0]

    @classmethod
    def translate(cls, mediatek_ues, taf_configuration):
        mediatek_info = {}
        appserver = taf_configuration.appserver
        for ue_no, ue in enumerate(mediatek_ues):
            ue_name = cls._create_ue_name(ue_no)
            all_capabilities = cls._get_capabilities(ue)
            configuration = cls._get_configuration_info(ue, appserver)

            constructor_parameters = {'configuration': configuration}
            mediatek_info[ue_name] = {
                'CAPABILITIES': all_capabilities,
                'CLASS': cls.class_name,
                'CONSTRUCTOR_PARAMETERS': constructor_parameters}
        return {'inline_config': mediatek_info}

    @classmethod
    def _create_ue_name(cls, ue_no):
        ue_name = f'{cls.pool_name}_{ue_no}'
        return ue_name

    @classmethod
    def _get_capabilities(cls, ue):
        if ue.capabilities is not None:
            return cls.capabilities + ue.capabilities
        return cls.capabilities

    @staticmethod
    def _get_data_transfer_info(ue, appserver):

        app_server = None
        if appserver:
            app_server = {'addr': appserver.iperf_details.ssh_connection_details.addr,
                          'username': appserver.iperf_details.ssh_connection_details.username,
                          'password': appserver.iperf_details.ssh_connection_details.password,
                          'iperf_ports': appserver.iperf_details.ports,
                          'iperf_path': appserver.iperf_details.iperf_path,
                          'iperf_interface_ip': appserver.iperf_details.network_interface_address
                          }

        ue_host = None
        if ue.iperf_details:
            ue_host = {'addr': ue.iperf_details.ssh_connection_details.addr,
                       'username': ue.iperf_details.ssh_connection_details.username,
                       'password': ue.iperf_details.ssh_connection_details.password,
                       'iperf_ports': ue.iperf_details.ports,
                       'iperf_path': ue.iperf_details.iperf_path}

        return ue_host, app_server, ue.apn_url

    @classmethod
    def _get_configuration_info(cls, ue, appserver):
        ssh_conn = ue.ssh_connection_details

        com_port = 'portname:COM' + str(ue.com_port) if ue.com_port != 'auto' else ue.com_port
        configuration = {'ue_pc_ip': ssh_conn.addr,
                         'pyro_port': ue.server_port,
                         'login': ssh_conn.username,
                         'password': ssh_conn.password,
                         'server_dir': ue.server_dir,
                         'edb_file_path': ue.edb_file_path,
                         'imei': ue.imei,
                         'log_filter': ue.log_filter,
                         'com_port': com_port,
                         'server_python': ue.python_path,
                         'serial_number': ue.serial_number
                         }
        if ue.iperf_details is not None:
            ue_host, app_server, apn = cls._get_data_transfer_info(ue, appserver)
            configuration['data_transfer'] = {
                'pdn_name': apn,
                'app_server': app_server,
                'ue_host': ue_host
            }

        return configuration


class UteUeIperfDataTransferTranslator:

    @classmethod
    def uses_adb(cls, ue):
        if ue.__class__.__name__ == 'Android':
            return True
        if hasattr(ue, 'serial_number'):
            if hasattr(ue, 'adb_shell_prompt') or hasattr(ue, 'iperf_from_adb_shell'):
                return True
        return False

    @classmethod
    def get_adb_prompt(cls, ue):
        adb_prompt = r'^[^@]+~[$#]\s*$'  # default
        if hasattr(ue, 'adb_shell_prompt'):
            adb_prompt = ue.adb_shell_prompt
        return adb_prompt

    @classmethod
    def get_start_from(cls, ue):
        if cls.uses_adb(ue):
            start_from = 'adb_shell'
        else:
            start_from = 'ue_pc'
        if hasattr(ue, 'iperf_from_adb_shell'):
            start_from = 'adb_shell' if ue.iperf_from_adb_shell else 'ue_pc'
        return start_from

    @classmethod
    def get_need_root(cls, ue):
        if cls.uses_adb(ue):
            need_root = True
        else:
            need_root = False
        if hasattr(ue, 'iperf_need_root'):
            need_root = False if ue.iperf_need_root is None else ue.iperf_need_root
        return need_root

    @classmethod
    def get_need_sudo(cls, ue):
        need_sudo = False
        if hasattr(ue, 'iperf_need_sudo'):
            need_sudo = False if ue.iperf_need_sudo is None else ue.iperf_need_sudo
        return need_sudo

    @classmethod
    def get_root_password(cls, ue):
        root_password = None
        if hasattr(ue, 'root_password'):
            root_password = ue.root_password
        return root_password

    @classmethod
    def get_iperf_port(cls, iperf_details):
        try:
            port = iperf_details.port
            if port is not None:
                port = int(port)
        except AttributeError:
            port = None
        return port

    @classmethod
    def get_iperf_descr(cls, ue):
        iperf_descr = {
            'start_from': cls.get_start_from(ue),
            'path': ue.iperf_details.iperf_path,
            'need_root': cls.get_need_root(ue),
            'need_sudo': cls.get_need_sudo(ue)
            # 'use_sudo_when': 'port<1024',  # we take this default
        }
        port = cls.get_iperf_port(ue.iperf_details)
        if port is not None:
            iperf_descr['port'] = port
        return iperf_descr

    @classmethod
    def get_host_descr(cls, ssh_connection_details):
        host_ssh_descr = {
            'host': ssh_connection_details.addr,
            'ssh_port': ssh_connection_details.port,
            'login': ssh_connection_details.username,
            'password': ssh_connection_details.password,
        }
        return host_ssh_descr

    @classmethod
    def get_data_transfer_descr(cls, ue):
        dt_def = {
            'ue_host': cls.get_host_descr(ue.ssh_connection_details),
            'ue_ip': ue.iperf_details.network_interface_address,
            'default_app_server_index': 0,
            'iperf': cls.get_iperf_descr(ue)
        }
        root_passwd = cls.get_root_password(ue)
        if root_passwd is not None:
            dt_def['ue_host']['root_password'] = root_passwd
        if cls.uses_adb(ue):
            dt_def['ue_host']['adb'] = {
                'serial_number': ue.serial_number,
                'expected_prompt': cls.get_adb_prompt(ue)
            }
        return dt_def


class DemoUeTranslator:
    pool_name = 'DemoUePool'
    capabilities = ['DEMO_UE']
    class_name = pool_name.split('Pool')[0]

    @classmethod
    def translate(cls, demo_ues, taf_configuration):
        demoue_info = {}
        for ue_no, ue in enumerate(demo_ues):
            ue_name = cls._create_ue_name(ue_no)
            all_capabilities = cls._get_capabilities(ue)
            configuration = cls._get_configuration_info(ue_no, ue)

            constructor_parameters = {'configuration': configuration}
            demoue_info[ue_name] = {
                'CAPABILITIES': all_capabilities,
                'CLASS': cls.class_name,
                'CONSTRUCTOR_PARAMETERS': constructor_parameters}
        return {'inline_config': demoue_info}

    @classmethod
    def _create_ue_name(cls, ue_no):
        ue_name = f'{cls.pool_name}_{ue_no}'
        return ue_name

    @classmethod
    def _get_capabilities(cls, ue):
        if ue.capabilities is not None:
            return list(set(cls.capabilities + ue.capabilities))
        return cls.capabilities

    @classmethod
    def _get_configuration_info(cls, ue_no, ue):
        configuration = {
            'id': ue_no,
        }
        if ue.iperf_details is not None:
            configuration['data_transfer'] = UteUeIperfDataTransferTranslator.get_data_transfer_descr(ue)

        return configuration


