"""
This dict maps class names of objects given in tl.ues to their ute_ue
translator classes.
"""
taf_ue_translators = {
    'Prisma': PrismaUeTranslator,
    'TM500': ViaviUeTranslator,
    'Qualcomm': QualcommUeTranslator,
    'Android': AndroidUeTranslator,
    # translators for new implementation of taf.ue.proxy plugin:
    'TafUeAndroid': TafUeAndroidTranslator,
    'TafUeIphone': TafUeIphoneTranslator,
    'TafUeAt': TafUeAtTranslator,
    'TafUeFastmile': TafUeFastmileTranslator,
    'TafUeMtk': TafUeMtkTranslator,
    'UltraCaller': UltraCallerUeTranslator,
    'MediaTek': MediaTekTranslator,
    'DemoUe': DemoUeTranslator,
    'dict': UteUeDictTranslator
}


def translate_taf_to_ute_ue(taf_configuration):
    """ Translate taf_configuration into ute_ue-style config dictionary. """
    taf_ues = taf_configuration.ues

    if not taf_ues:
        logger.info("No UEs found in TAF configuration")
        return

    translators_ues = _assign_ues_to_translators(taf_ues)
    config = TranslatedConfig()

    for translator, ues_to_translate in translators_ues.items():
        ue_pool_name = translator.pool_name
        try:
            ue_pool_config = translator.translate(ues_to_translate,
                                                  taf_configuration)
        except NotImplementedError:
            warn_msg = "Uninmplemented translate method for {}"
            warn_msg = warn_msg.format(ue_pool_name)
            logger.warning(warn_msg)
            continue

        config.add_pool_config(ue_pool_name, ue_pool_config)

    _translate_pdn_to_ute_ue(taf_configuration, config)
    _translate_appserver_to_ute_ue(taf_configuration, config)

    return config


def _translate_pdn_to_ute_ue(taf_configuration, translated_configuration):
    """ Translate taf_configuration into ute_ue-style config dictionary. """
    if taf_configuration.core is None:
        return

    if taf_configuration.core.pdns is None:
        return

    for pdn in taf_configuration.core.pdns:
        pdn_config = {'apn': pdn.apn}
        pdp_type_config = {'pdp_type': pdn.pdp_type}
        for pool_name in translated_configuration.get_pool_names():
            pdn_config.update({pool_name: pdp_type_config})
        translated_configuration.add_pdn_config(pdn.apn, pdn_config)


def _translate_appserver_to_ute_ue(taf_configuration, translated_configuration):
    """ Translate taf_configuration into ute_ue-style config dictionary. """
    if taf_configuration.appservers is None:
        return

    for index, app_server in enumerate(taf_configuration.appservers):
        if app_server is None:
            continue
        ssh_conn = app_server.iperf_details.ssh_connection_details
        appserver_config = {
            'host': UteUeIperfDataTransferTranslator.get_host_descr(ssh_conn),
            'bind_interface_ip': app_server.iperf_details.network_interface_address,
            'iperf': {
                'path': app_server.iperf_details.iperf_path
                # 'use_sudo_when': 'port<1024',  # we take this default
            }
        }
        port = UteUeIperfDataTransferTranslator.get_iperf_port(app_server.iperf_details)
        if port is not None:
            appserver_config['iperf']['port'] = port
        translated_configuration.add_appserver_config(appserver_config)


def _assign_ues_to_translators(ues):
    translators_ues = {}

    for ue in ues:
        class_name = ue.__class__.__name__
        translator_class = taf_ue_translators.get(class_name)

        if translator_class is None:
            msg = ("Found a TAF UE configuration object that has no "
                   f"corresponding ute_ue translator: {ue}. Skipping.")
            logger.info(msg)
            continue

        translator_ues = translators_ues.setdefault(translator_class, [])
        translator_ues.append(ue)

    return translators_ues


class TranslatedConfig(dict):
    def __init__(self):
        super().__init__()
        self['VERSION'] = 2.0
        self['UE_POOLS'] = {}
        self['PDN'] = {}
        self['APP_SERVERS'] = []

    def add_pool_config(self, ue_pool_name, ue_pool_config):
        if ue_pool_name is None:
            self['UE_POOLS'].update(ue_pool_config['UE_POOLS'])
        else:
            self['UE_POOLS'][ue_pool_name] = ue_pool_config

    def get_pool_names(self):
        return self['UE_POOLS'].keys()

    def add_pdn_config(self, pdn_name, pdn_config):
        self['PDN'][pdn_name] = pdn_config

    def add_appserver_config(self, appserver_config):
        self['APP_SERVERS'].append(appserver_config)
